import{_ as a,o as s,c as t,a0 as i}from"./chunks/framework.t4Rf69I2.js";const g=JSON.parse('{"title":"Packaging and Release","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/packaging.md","filePath":"en/guide/packaging.md","lastUpdated":1785233645000}'),n={name:"en/guide/packaging.md"};function l(o,e,p,r,d,c){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="packaging-and-release" tabindex="-1">Packaging and Release <a class="header-anchor" href="#packaging-and-release" aria-label="Permalink to &quot;Packaging and Release&quot;">​</a></h1><p>This project builds its release pipeline around <strong>goreleaser</strong>: first generate the <code>.deb</code> package, then produce and sign the APT repository metadata, and finally publish to GitHub Pages. See <a href="./ci-cd">CI/CD Pipeline</a> for the full automated workflow.</p><h2 id="directory-structure" tabindex="-1">Directory Structure <a class="header-anchor" href="#directory-structure" aria-label="Permalink to &quot;Directory Structure&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>go-cipher-cli/</span></span>
<span class="line"><span>├── main.go                 # Entry point</span></span>
<span class="line"><span>├── cmd/                    # CLI commands (root / run / version)</span></span>
<span class="line"><span>├── .goreleaser.yml         # goreleaser configuration (generates .deb)</span></span>
<span class="line"><span>├── scripts/</span></span>
<span class="line"><span>│   ├── package.sh          # Packaging script (generates .deb)</span></span>
<span class="line"><span>│   └── publish_repo.sh     # APT repository publishing script</span></span>
<span class="line"><span>├── repo/conf/              # APT repository configuration (distributions)</span></span>
<span class="line"><span>├── docs/                   # VitePress documentation site source</span></span>
<span class="line"><span>└── .github/workflows/      # GitHub Actions workflows</span></span></code></pre></div><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Purpose</th><th>Install Command</th></tr></thead><tbody><tr><td><code>go</code> &gt;= 1.21</td><td>Compile the binary</td><td>See <a href="https://go.dev/dl/" target="_blank" rel="noreferrer">https://go.dev/dl/</a></td></tr><tr><td><code>goreleaser</code></td><td>Generate <code>.deb</code> (recommended)</td><td><code>go install github.com/goreleaser/goreleaser@latest</code></td></tr><tr><td><code>dpkg-deb</code></td><td>Build <code>.deb</code> manually (fallback, bundled with Debian/Ubuntu)</td><td><code>apt install dpkg-dev</code></td></tr><tr><td><code>reprepro</code></td><td>Generate APT repository metadata (recommended)</td><td><code>apt install reprepro</code></td></tr><tr><td><code>aptly</code></td><td>Generate APT repository metadata (alternative)</td><td>See <a href="https://www.aptly.info/" target="_blank" rel="noreferrer">https://www.aptly.info/</a></td></tr><tr><td><code>apt-ftparchive</code></td><td>Generate repository metadata (fallback when reprepro unavailable)</td><td><code>apt install apt-utils</code></td></tr><tr><td><code>gpg</code></td><td>Sign <code>Release</code>/<code>InRelease</code></td><td><code>apt install gnupg</code></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Fallback Mechanism</p><p>Both <code>package.sh</code> and <code>publish_repo.sh</code> have automatic fallbacks: when goreleaser is unavailable they fall back to dpkg-deb, and when reprepro/aptly is unavailable they fall back to apt-ftparchive. So even with an incomplete toolchain, basic packaging can still be completed.</p></div><h2 id="two-step-process" tabindex="-1">Two-Step Process <a class="header-anchor" href="#two-step-process" aria-label="Permalink to &quot;Two-Step Process&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────┐     ┌──────────────────────────┐</span></span>
<span class="line"><span>│  Step 1: Package │     │  Step 2: Publish          │</span></span>
<span class="line"><span>│  scripts/        │ ──&gt; │  scripts/publish_repo.sh  │</span></span>
<span class="line"><span>│  package.sh      │     │  Generates dists/ pool/   │</span></span>
<span class="line"><span>│  Generates .deb  │     │  Signs Release/InRelease  │</span></span>
<span class="line"><span>└──────────────────┘     └──────────────────────────┘</span></span></code></pre></div><h3 id="step-1-generate-the-deb" tabindex="-1">Step 1: Generate the .deb <a class="header-anchor" href="#step-1-generate-the-deb" aria-label="Permalink to &quot;Step 1: Generate the .deb&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/package.sh</span></span></code></pre></div><p>Script logic (with priority-based fallback):</p><ol><li><strong>goreleaser</strong> (preferred): runs <code>goreleaser release --snapshot --clean</code>; output is in <code>dist/</code>.</li><li><strong>dpkg-deb</strong> (fallback): when goreleaser is unavailable, builds the binary manually and packages it with <code>dpkg-deb --build</code>.</li></ol><p>Output: <code>dist/go-cipher-cli_&lt;version&gt;_linux_amd64.deb</code></p><p>The goreleaser configuration is in <a href="https://github.com/kulaiyin/go-cipher-cli/blob/main/.goreleaser.yml" target="_blank" rel="noreferrer"><code>.goreleaser.yml</code></a>, where the <code>nfpms</code> section defines the package name, maintainer, description, and install path (automatically installed to <code>/usr/bin/go-cipher-cli</code>).</p><h4 id="using-only-goreleaser-optional" tabindex="-1">Using Only goreleaser (Optional) <a class="header-anchor" href="#using-only-goreleaser-optional" aria-label="Permalink to &quot;Using Only goreleaser (Optional)&quot;">​</a></h4><p>If you want to build only with <code>goreleaser</code> (skipping the fallback logic):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">goreleaser</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --snapshot</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --clean</span></span></code></pre></div><h4 id="inspecting-the-deb" tabindex="-1">Inspecting the .deb <a class="header-anchor" href="#inspecting-the-deb" aria-label="Permalink to &quot;Inspecting the .deb&quot;">​</a></h4><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dpkg-deb</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -I</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist/go-cipher-cli_0.1.0_linux_amd64.deb</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # View control info</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dpkg-deb</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist/go-cipher-cli_0.1.0_linux_amd64.deb</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # View file list</span></span></code></pre></div><h3 id="step-2-publish-to-the-apt-repository" tabindex="-1">Step 2: Publish to the APT Repository <a class="header-anchor" href="#step-2-publish-to-the-apt-repository" aria-label="Permalink to &quot;Step 2: Publish to the APT Repository&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/publish_repo.sh</span></span></code></pre></div><p>This script reads the latest <code>.deb</code> in <code>dist/</code> and generates the APT repository metadata. For detailed usage of the three tools and their fallback order, see <a href="./apt-repo">APT Repository and GitHub Pages</a>.</p><h2 id="related-topics" tabindex="-1">Related Topics <a class="header-anchor" href="#related-topics" aria-label="Permalink to &quot;Related Topics&quot;">​</a></h2><ul><li><a href="./apt-repo">APT Repository and GitHub Pages</a>: three repository metadata generation approaches, GitHub Pages hosting, and client installation.</li><li><a href="./ci-cd">CI/CD Pipeline</a>: the fully automated release flow triggered by pushing a tag, and signing key management.</li></ul>`,25)])])}const b=a(n,[["render",l]]);export{g as __pageData,b as default};
